IF EXISTS (SELECT * FROM dbo.sysobjects WHERE id = OBJECT_ID('usp_GetPaymentSlacompliance'))BEGIN    DROP PROCEDURE dbo.usp_GetPaymentSlacomplianceEND
SET ANSI_NULLS ONGOSET QUOTED_IDENTIFIER ONGOCreate PROCEDURE usp_GetPaymentSlacompliance    @actionstatus varchar(20)    AS    BEGIN    if(@actionstatus='SLACompleted')    begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,ps.IsApproved,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview        From PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.id    outer apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshwhere ISNull(ps.IsApproved,0)!=0    end    else if(@actionstatus='FakeReport')       begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview,Case when imj.Joinedon is null and imc.PerformedOn is null then 'No Show' when imj.Joinedon is null then 'Interviewer No Show' when imc.PerformedOn is null then 'Candidate No Show' end as StatusValueFrom PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.id outer apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshouter apply(Select max(PerformedOn) PerformedOn From PageClickDetails where ButtonAction='JoinMeeting' and Interviewid=im.id and ProfileType='Candidate') imc  where ISNull(ps.IsApproved,0)=0 and im.ZoomMeetingId in(Select distinct Meetingid from ZoomMeetingTransmission) and IsAIInterview=0 and (imj.Joinedon is null or imc.PerformedOn is null)endelse if(@actionstatus='RedoRequested')       begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview,Case when imj.Joinedon is null and imc.PerformedOn is null then 'No Show' when imj.Joinedon is null then 'Interviewer No Show' when imc.PerformedOn is null then 'Candidate No Show' end as StatusValueFrom PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.idleft join QcInterviewAIevaluation qia on qia.InterviewId=ps.Interviewidouter apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshouter apply(Select max(PerformedOn) PerformedOn From PageClickDetails where ButtonAction='JoinMeeting' and Interviewid=im.id and ProfileType='Candidate') imc  where ISNull(ps.IsApproved,0)=0 and ISNULL(qia.AIMergeRedoInterview,0)=1endelse if(@actionstatus='HighSeverityPending')       begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview,d.DeficitType as StatusValueFrom PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.idouter apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshLEFT JOIN (SELECT InterviewId,STRING_AGG(Type, ',') AS DeficitType FROM(Select im.id AS InterviewId,'deficitmorethan10' as Type      
from InterviewMeetings im join InterviewComments ic on ic.InterviewId=im.id      
join IRF on IRF.IRFId=im.IRFId      
join PlanTypeChargesMaster pt on pt.CountryType=IRF.JobCountry and pt.PlanTypeEnumValue=IRF.Heuristicsscore and IRF.CompanyType=pt.CompanyType      
where (MeetingStatus=4) and DateDiff(Day,im.interviewDate,Getdate())<30      
and (ic.VideoDuration-pt.DurationSelectedMin)>(-pt.DurationSelectedMin) and (ic.VideoDuration-pt.DurationSelectedMin)<-10      
union      
--AI Transcript score <6      
Select im.id AS InterviewId,'AIVerdictLessthan4' as Type      
From InterviewMeetings im join InterviewComments ic on ic.InterviewId=im.id      
join IRF on IRF.IRFId=im.IRFId      
join Client cl on cl.id=IRF.ClientId      
where (MeetingStatus=4 or MeetingStatus=6 or MeetingStatus=7 or MeetingStatus=8) and DateDiff(Day,im.interviewDate,Getdate())<30      
and ic.AITranscriptAnalysisScore<4      
union      
--Candidate Rating <4      
Select im.id AS InterviewId,'CandidateRating' as Type      
From InterviewMeetings im join InterviewComments ic on ic.InterviewId=im.id      
join IRF on IRF.IRFId=im.IRFId      
join Client cl on cl.id=IRF.ClientId      
join CandidateFeedbackDetails cfd on cfd.InterviewId=im.id      
where (MeetingStatus=4 or MeetingStatus=6 or MeetingStatus=7 or MeetingStatus=8) and DateDiff(Day,im.interviewDate,Getdate())<30  and cfd.Rating<4) x GROUP BY InterviewId) d ON d.InterviewId = im.idwhere ISNull(ps.IsApproved,0)=0  and d.DeficitType is not nullendelse if(@actionstatus='QCUnderReview')       begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview,d.DeficitType as StatusValueFrom PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.idouter apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshLEFT JOIN (SELECT InterviewId,STRING_AGG(Type, ',') AS DeficitType FROM (
        SELECT im.id AS InterviewId,'Selectdeficit' AS Type
        FROM InterviewMeetings im JOIN InterviewComments ic ON ic.InterviewId = im.id JOIN IRF ON IRF.IRFId = im.IRFId
        JOIN PlanTypeChargesMaster pt ON pt.CountryType = IRF.JobCountry AND pt.PlanTypeEnumValue = IRF.Heuristicsscore AND IRF.CompanyType = pt.CompanyType
        WHERE ic.MeetingStatus IN (4,6,7,8) AND (pt.DurationSelectedMin*2/3 > ic.VideoDuration) AND ic.InterviewStatus IN (2,4)
        UNION 
        SELECT im.id AS InterviewId,'Rejectdeficit' AS Type
        FROM InterviewMeetings im JOIN InterviewComments ic ON ic.InterviewId = im.id JOIN IRF ON IRF.IRFId = im.IRFId
        JOIN PlanTypeChargesMaster pt ON pt.CountryType = IRF.JobCountry AND pt.PlanTypeEnumValue = IRF.Heuristicsscore AND IRF.CompanyType = pt.CompanyType
        WHERE ic.MeetingStatus IN (4,6,7,8) AND (pt.DurationSelectedMin*4/9 > ic.VideoDuration) AND ic.InterviewStatus IN (1,3,5)) x GROUP BY InterviewId) d ON d.InterviewId = im.idwhere ISNull(ps.IsApproved,0)=0 and d.DeficitType is not nullendelse if(@actionstatus='QCSelectPending')beginSelect ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview,Case when ISNull(ps.IsApproved,0)=1 then 'Approved' when ISNull(ps.IsApproved,0)=2 then 'Not Approved' else '' end as StatusValue     From PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join InterviewComments ic on ic.Interviewid=im.idleft join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.id outer apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshwhere (ic.InterviewStatus=4 or ic.InterviewStatus=2)endelse    begin    Select ps.*,IRF.IRFId,IRF.id as irfIntId,im.candidateEmail,im.interviewer,im.interviewDate,ul.EmailId as ChannelOwner,ip.CompanyName, ip.ResumeLink, ip.RedMarker, uli.MobileNumber,im.MobileNumber as CandidatePhone,RTRIM(LTRIM((ISNULL(uli.FirstName,'')+' '+ISNULL(uli.LastName,'')))) as InterviewerName,tq.Redflags,Case when tq.id>0 then 1 else 0 end as QCStatus,    imj.Joinedon,im.candidateName,psh.TotalPaymentComplianceCount,im.SessionId,IRF.IsAIInterview     From PaymentSLADetails ps left join InterviewMeetings im on ps.Interviewid=im.id     left join IRF on IRF.IRFId=im.IRFId     left join UserList ul on ul.id=IRF.RisebirdHr    left join UserList uli on uli.EmailId=im.interviewer    left join InterviewerProfile ip on ip.UserId=uli.id    left join Trans_QCFormReport tq on tq.interviewid=im.id outer apply(Select Min(Joinedon) Joinedon from InterviewMeetingsJoinTime where interviewid=im.id) as imjouter apply(Select Count(id) as TotalPaymentComplianceCount  From PaymentSLADetailsHistory where Interviewid=ps.Interviewid) as pshwhere ISNull(ps.IsApproved,0)=0    endEND GO
